const text = $json.output || $json.message || "";

/*
FORMATADOR WHATSAPP — VERSÃO ESTÁVEL
- NÃO quebra frases no meio
- Organiza blocos (SIMULAÇÃO, listas)
- Corrige travessão
- Mantém naturalidade
- Escapa caracteres que quebram JSON no HTTP Request
*/

// --------------------------------------------------
let formatted = text
  .replace(/\\n/g, "\n")
  .replace(/\r/g, "")
  .trim();

// --------------------------------------------------
// 🔥 1. Corrigir travessão (sem quebrar palavra)
formatted = formatted.replace(/\s*—\s*/g, ".\n\n");

// Corrigir quebra errada tipo "pré\nanálise"
formatted = formatted.replace(/(\w)\n(\w)/g, "$1 $2");

// --------------------------------------------------
// 🔥 2. Garantir quebra antes de blocos importantes
formatted = formatted.replace(/📊\s*SIMULAÇÃO/gi, "\n\n📊 SIMULAÇÃO");

// --------------------------------------------------
// 🔥 3. Organizar listas (➡️ sempre nova linha)
formatted = formatted.replace(/\s*➡️\s*/g, "\n➡️ ");

// --------------------------------------------------
// 🔥 4. Separar frases muito longas APENAS se necessário
formatted = formatted.replace(/([a-z])\.\s+([A-Z])/g, "$1.\n\n$2");

// --------------------------------------------------
// 🔥 5. Garantir espaçamento correto entre parágrafos
let lines = formatted
  .split("\n")
  .map(l => l.trim())
  .filter(Boolean);

// Remove duplicadas
lines = lines.filter((line, i) => line !== lines[i - 1]);

// Junta padrão WhatsApp
formatted = lines.join("\n\n");

// Evita excesso de quebra
formatted = formatted.replace(/\n{3,}/g, "\n\n");

// --------------------------------------------------
// 🔥 6. Escape para JSON válido no HTTP Request
formatted = formatted
  .replace(/\\/g, "\\\\")   // barra invertida primeiro
  .replace(/"/g, '\\"')     // aspas duplas
  .replace(/\n/g, "\\n")    // quebras de linha
  .replace(/\r/g, "\\r")    // carriage return residual
  .replace(/\t/g, "\\t");   // tabs eventuais

return [
  {
    json: {
      message: formatted
    }
  }
];

