// Pega os valores de renda e extra
const rendaRaw = $json.renda || "0";
const extraRaw = $json.extra || "0";

// Limpa e converte para número (remove R$, pontos, substitui vírgula por ponto)
function parseValor(valor) {
  return parseFloat(
    String(valor)
      .replace(/R\$\s?/g, '')
      .replace(/\./g, '')
      .replace(',', '.')
      .trim()
  ) || 0;
}

const renda = parseValor(rendaRaw);
const extra = parseValor(extraRaw);
const rendaTotal = renda + extra;

// Define a faixa — atualizado conforme regras de abril/2026
let faixa;
let faixaDescricao;

if (rendaTotal <= 3200) {
  faixa = 1;
  faixaDescricao = "Até R$ 3.200";
} else if (rendaTotal <= 5000) {
  faixa = 2;
  faixaDescricao = "Até R$ 5.000";
} else if (rendaTotal <= 9600) {
  faixa = 3;
  faixaDescricao = "Até R$ 9.600";
} else if (rendaTotal <= 13000) {
  faixa = 4;
  faixaDescricao = "Até R$ 13.000";
} else {
  faixa = null;
  faixaDescricao = "Acima das faixas disponíveis";
}

return [{
  json: {
    ...$json, // mantém todos os dados anteriores
    renda_formal: renda,
    renda_extra: extra,
    renda_total: rendaTotal,
    renda_total_formatada: rendaTotal.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' }),
    faixa,
    faixa_descricao: faixaDescricao,
    elegivel: faixa !== null
  }
}];

function padronizarValor(input) {
  if (!input) return "R$ 0,00";
  let texto = String(input).toLowerCase().trim();
  const ruidos = [/r\$/g, /reais/g, /aprox\./g, /aproximadamente/g, /mais ou menos/g, /uns/g, /cerca de/g, /eu ganho/g, /ganho/g, /na faixa de/g, /ate/g, /até/g, /de /g];
  ruidos.forEach(regex => { texto = texto.replace(regex, '').trim(); });
  if (texto.includes('salario') || texto.includes('salário')) {
    let qtd = texto.match(/[\d.,]+/);
    let multiplicador = qtd ? parseFloat(qtd[0].replace(',', '.')) : 1;
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(multiplicador * 1621);
  }
  const mapaExtenso = {
    "sem": "100", "cem": "100", "cento": "100",
    "duzentos": "200", "trezentos": "300", "quatrocentos": "400", "quinhentos": "500",
    "seiscentos": "600", "setecentos": "700", "oitocentos": "800", "novecentos": "900",
    "mil": "1000", "um mil": "1000",
    "mil e cem": "1100", "mil e duzentos": "1200", "mil e trezentos": "1300",
    "mil e quatrocentos": "1400", "mil e quinhentos": "1500",
    "dois mil": "2000", "tres mil": "3000", "três mil": "3000",
    "quatro mil": "4000", "cinco mil": "5000"
  };
  if (mapaExtenso[texto]) { texto = mapaExtenso[texto]; }
  let multiplicaMil = false;
  if (texto.includes('mil') || texto.includes('k')) {
    multiplicaMil = true;
    texto = texto.replace(/mil/g, '').replace(/k/g, '');
  }
  let matchNumero = texto.match(/[\d.,]+/);
  if (!matchNumero) return "R$ 0,00";
  texto = matchNumero[0];
  if (texto.includes(',')) {
    texto = texto.replace(/\./g, '').replace(',', '.');
  } else if (!multiplicaMil) {
    texto = texto.replace(/\./g, '');
  }
  let valor = parseFloat(texto);
  if (isNaN(valor)) valor = 0;
  if (multiplicaMil) { valor = valor * 1000; }
  return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(valor);
}

// --- CÓDIGO PRINCIPAL --- //
const entry = $('Webhook EVO').first().json.body.entry[0].changes[0].value;
const raw = entry.messages[0].interactive.nfm_reply.response_json;
const formulario = JSON.parse(raw);

return [{
  json: {
    // Identificação
    numero:                 entry.contacts[0].wa_id,
    nome:                   formulario.nome,
    cpf:                    formulario.cpf,
    data_nascimento:        formulario.data_nascimento,
    email:                  formulario.email || "não enviado",  // ✅
    telefone:               formulario.telefone,
    // Perfil familiar
    estado_civil:           formulario.estado_civil,
    possui_dependentes:     formulario.possui_dependentes,
    quantidade_dependentes: formulario.quantidade_dependentes || 0, // ✅
    // FGTS
    possui_fgts:            formulario.possui_fgts,
    valor_fgts:             padronizarValor(formulario.valor_fgts),
    // Renda
    clt:                    formulario.clt,
    renda:                  padronizarValor(formulario.renda_clt),
    extra:                  padronizarValor(formulario.renda_extra),
    // Perfil habitacional
    mora_extremoz:          formulario.mora_extremoz,
    possui_imovel:          formulario.possui_imovel,
    financiamento:          formulario.financiamento,
  }
}];

