<script>
  // Este código pega o "id" e o "conversation_id" da URL e coloca nos campos escondidos
  window.onload = function() {
    const urlParams = new URLSearchParams(window.location.search);

    const id = urlParams.get('id');
    if (id) {
      document.getElementById('usuario_id').value = id;
    }

    const conversationId = urlParams.get('conversation_id');
    if (conversationId) {
      document.getElementById('conversation_id').value = conversationId;
    }
  }

  function selectFile(id) {
    document.getElementById(id).click();
  }

  function dragOver(event) {
    event.preventDefault();
  }

  function dropHandler(event, id) {
    event.preventDefault();
    const files = event.dataTransfer.files;
    const input = document.getElementById(id);
    input.files = files;
    showFileName(id, files[0]);
  }

  function showFileName(id, file) {
    if (file) {
      document.getElementById("name-" + id).innerText = file.name;
    }
  }

  document.querySelectorAll("input[type=file]").forEach(input => {
    input.addEventListener("change", (e) => {
      const file = e.target.files[0];
      showFileName(e.target.id, file);
    });
  });

  document.getElementById("form").addEventListener("submit", function(e) {
    e.preventDefault();

    // Adiciona feedback visual no botão enquanto envia
    const btn = document.querySelector(".btn");
    const originalText = btn.innerHTML;
    btn.innerHTML = "Enviando...";
    btn.disabled = true;

    const formData = new FormData();

    for (let i = 1; i <= 4; i++) {
      const file = document.getElementById("file" + i).files[0];
      if (file) {
        formData.append("file" + i, file);
      }
    }

    // Pega o ID e o conversation_id capturados da URL e adiciona no envio
    const idCliente = document.getElementById('usuario_id').value;
    formData.append("idCliente", idCliente);

    const conversationId = document.getElementById('conversation_id').value;
    formData.append("conversationId", conversationId);

    console.log("Arquivos prontos para envio");

    // Integração com Webhook do n8n e tela de sucesso
    fetch("https://webhook.grupocachina.com.br/webhook/MCA-Recebe", {
      method: "POST",
      body: formData
    })
    .then(response => {
      // Cria a tela de sucesso
      document.body.innerHTML = `
        <div style="display: flex; justify-content: center; align-items: center; height: 100vh; font-family: Arial, sans-serif; text-align: center; background-color: #f5f5f5;">
