            <p style="color: #333; font-size: 16px;">Os documentos foram enviados com sucesso.</p>
            <p style="color: #666; font-size: 14px; margin-top: 20px;"><strong>Você já pode fechar esta aba e voltar para o WhatsApp.</strong></p>
          </div>
        </div>
      `;
    })
    .catch(error => {
      console.error("Erro:", error);
      alert("Ocorreu um erro ao enviar. Tente novamente.");
      // Retorna o botão ao estado normal caso dê erro
      btn.innerHTML = originalText;
      btn.disabled = false;
    });
  });
</script>

</body>
