const ativa = conversas
  ?.filter(c => ['open', 'pending'].includes(c.status) && c.inbox_id === 27)
  .sort((a, b) => b.id - a.id)[0];

return [{
  json: {
    ...dados,
    conversation_id: ativa ? ativa.id : null,
    inbox_id: ativa ? ativa.inbox_id : 27,
    conversa_existe: !!ativa,
    conversation_status: ativa ? ativa.status : null  // 'open', 'pending' ou null
  }
}];

