const body = $json.body;
const msg = body.entry?.[0]?.changes?.[0]?.value?.messages?.[0];

let texto = null;
let tipo = null;
let conteudo = null;

// Texto simples
if (msg?.text) {
  texto = msg.text.body;
  tipo = "texto";
  conteudo = msg.text.body;
}
// Botão
else if (msg?.interactive?.type === "button_reply") {
  texto = msg.interactive.button_reply.title;
  tipo = "botao";
  conteudo = msg.interactive.button_reply.title;
}
// Lista
else if (msg?.interactive?.type === "list_reply") {
  texto = msg.interactive.list_reply.title;
  tipo = "lista";
  conteudo = msg.interactive.list_reply.title;
}
// Flow (WhatsApp Flows)
else if (msg?.interactive?.type === "nfm_reply") {
  texto = msg.interactive.nfm_reply;
  tipo = "flow";
  conteudo = msg.interactive.nfm_reply;
}
// Documento
else if (msg?.document) {
  tipo = "document";
  conteudo = msg.document.filename || msg.document.id || "";
  texto = conteudo;
}
// Imagem
else if (msg?.image) {
  tipo = "image";
  conteudo = msg.image.caption || msg.image.id || "";
  texto = conteudo;
}
// Áudio
else if (msg?.audio) {
  tipo = "audio";
  conteudo = msg.audio.id || "";
  texto = conteudo;
}

return [{
  json: {
    ...$json, // 🔥 mantém TUDO que chegou no webhook
    texto,
    tipo,
    conteudo,
    from: msg?.from,
    message_id: msg?.id,
    timestamp: msg?.timestamp
  }
}];

